"use client";
import {ArtemisScope} from "./artemis-scope";
import type { ArtemisCtaContent } from "./components/cta-sections/content";
import View8 from "./components/cta-sections/variants/09-faq";
const views={"faq":View8};
export type { ArtemisCtaContent, ArtemisCtaImage, ArtemisCtaLink, ArtemisCtaQuestion, ArtemisCtaStat } from "./components/cta-sections/content";
export interface ArtemisCtaSectionsProps{className?:string;variant?:"faq"; /** The words on the CTA section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisCtaContent>; }
export function ArtemisCtaSections({className,variant="faq",content}:ArtemisCtaSectionsProps){const View=views[variant];return <ArtemisScope className={className}><View content={content}/></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisCtaLink {
  label: string;
  href: string;
}

/** A picture, and the words that describe it. */
export interface ArtemisCtaImage {
  src: string;
  /** What the picture shows; empty for a purely decorative one. */
  alt: string;
}

/** A figure with a short label under it. */
export interface ArtemisCtaStat {
  /** The figure as text, such as "120" or "4.9". Its digits roll into place. */
  value: string;
  /** Shown right after the figure, such as "K+" or "/5". */
  suffix?: string;
  /** What the figure counts. */
  label: string;
}

/** A question and its answer. */
export interface ArtemisCtaQuestion {
  question: string;
  answer: string;
  /** A short id, unique in the list, used in the row's element ids. Defaults to the row's position. */
  id?: string;
}

/** The words on an Artemis CTA section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisCtaContent {
  /** The short line above the heading. sunflower, product-window, proof-orbit, shade-panel, glow and terminal. */
  badge?: string;
  /** The heading. All layouts. */
  headline: string;
  /** The heading's second part. glow shows it on a line of its own in a muted tone; faq, terminal and split start a new line for it; the other layouts run it on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** The paragraph under the heading. All layouts. */
  subhead: string;
  /** The main button. All layouts. */
  cta: ArtemisCtaLink;
  /** A second button. floating-gallery, portrait-frame, glow, terminal and split. */
  secondaryCta?: ArtemisCtaLink;
  /** A quiet text link under the buttons. split. */
  link?: ArtemisCtaLink;
  /** A short line near the buttons. sunflower, portrait-frame, proof-orbit and glow. */
  note?: string;
  /** The picture beside the words. portrait-frame, which also blurs it behind the panel, and glow. */
  image?: ArtemisCtaImage;
  /** Photos floating at the sides. floating-gallery: up to six, in pairs from the top, left then right; under 768px wide only the first two show. */
  images?: ArtemisCtaImage[];
  /** Faces in a row above the words. proof-orbit: up to five, from the left; the third is the largest. */
  avatars?: ArtemisCtaImage[];
  /** What the row of faces shows, read by screen readers. proof-orbit. Left out, it keeps the layout's own only when `avatars` is left out too. */
  avatarsLabel?: string;
  /** Figures under the buttons. floating-gallery; four look best. */
  stats?: ArtemisCtaStat[];
  /** Short facts along the foot of the panel. glow. */
  highlights?: string[];
  /** An install command with a copy button. terminal types it out; split shows it on its button. */
  command?: string;
  /** The lines the terminal prints after `command`. terminal. Left out, it keeps the layout's own lines only when `command` is left out too. */
  commandOutput?: string[];
  /** Questions with answers that open one at a time; the first starts open. faq. */
  questions?: ArtemisCtaQuestion[];
}

"use client";
// @zeus-internal
import { motion, type Transition, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { FaqAccordion, type FaqItem } from "./09-faq/faq-accordion";
import { TextReveal } from "./09-faq/text-reveal";
import type { ArtemisCtaContent } from "../content";
const IN_VIEW = { once: true } as const;
const reveal = (delay: number): Transition => ({ duration: 0.6, delay, ease: ARTEMIS_EASE_OUT });
const DEFAULT = {
    headline: "Ready to build",
    headlineAccent: "with Artemis?",
    subhead: "Premium motion components and blocks, copy-paste ready.",
    cta: { label: "Get Started Today", href: "#" },
    questions: [
        {
            id: "license",
            question: "What do I get with a license?",
            answer: "Reusable components and blocks with source included \u2014 ready to copy, paste, and customize for your next project.",
        },
        {
            id: "client-projects",
            question: "Can I use it in client projects?",
            answer: "Yes. Adapt the components for your personal and client projects, following the terms included with each item.",
        },
        {
            id: "stack",
            question: "Does it work with my stack?",
            answer: "Artemis is built for React, Next.js, and Tailwind CSS. Drop components straight into your app with no extra setup.",
        },
        {
            id: "install",
            question: "How do I install components?",
            answer: "Add components with the shadcn CLI from the Zeus registry, or copy the source directly from each component page.",
        },
        {
            id: "free-tier",
            question: "Is there a free version?",
            answer: "The Zeus library includes free components, blocks, and templates with source you can adapt to your project.",
        },
        {
            id: "updates",
            question: "Do you ship new components?",
            answer: "New components and blocks are added as they are ready. Browse the library for the latest available pieces.",
        },
    ],
} satisfies ArtemisCtaContent;
export default function CtaSectionsFaq({ content }: { content?: Partial<ArtemisCtaContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? copy.headlineAccent : content.headlineAccent;
    const items: FaqItem[] = copy.questions.map((item, index) => ({ id: item.id ?? `q${index}`, question: item.question, answer: item.answer }));
    const reduce = useReducedMotion();
    return (<div className="art:w-full">
      <section className="art:w-full art:px-4 art:py-16 art:@min-[640px]/artemis:px-8">
        <div className="art:mx-auto art:grid art:w-full art:max-w-6xl art:items-start art:gap-8 art:@min-[1024px]/artemis:grid-cols-2">
          <div className="art:relative art:flex art:min-h-[22rem] art:items-start art:overflow-hidden art:rounded-3xl art:border art:border-border art:bg-background art:p-8 art:pb-28 art:@min-[640px]/artemis:min-h-[28rem] art:@min-[640px]/artemis:p-12 art:@min-[640px]/artemis:pb-32 art:bg-[radial-gradient(ellipse_at_bottom_right,color-mix(in_oklab,var(--artemis-primary)_8%,transparent),transparent_70%)]">
            <svg aria-hidden="true" viewBox="0 0 560 450" preserveAspectRatio="xMaxYMax slice" className="art:pointer-events-none art:absolute art:inset-0 art:size-full art:text-primary">
                <ellipse cx="565" cy="485" rx="430" ry="310" fill="currentColor" fillOpacity="0.05"/>
                <ellipse cx="565" cy="485" rx="360" ry="260" fill="currentColor" fillOpacity="0.09" stroke="currentColor" strokeOpacity="0.12"/>
                <ellipse cx="565" cy="485" rx="290" ry="210" fill="currentColor" fillOpacity="0.15" stroke="currentColor" strokeOpacity="0.2"/>
                <ellipse cx="565" cy="485" rx="220" ry="160" fill="currentColor" fillOpacity="0.25" stroke="currentColor" strokeOpacity="0.3"/>
                <ellipse cx="565" cy="485" rx="150" ry="110" fill="currentColor" fillOpacity="0.5"/>
              </svg>
            <div className="art:relative">
              <TextReveal lines={accent ? [copy.headline, accent] : [copy.headline]} className="art:block art:max-w-md art:font-sans art:text-foreground art:text-4xl art:font-medium"/>
              <motion.p className="art:mt-4 art:max-w-sm art:text-pretty art:text-muted-foreground art:text-sm art:leading-7 art:@min-[640px]/artemis:text-base" initial={reduce?false:{ opacity: 0, filter: "blur(6px)", y: 12 }} animate={reduce?{opacity:1,y:0,filter:"blur(0px)"}:undefined} whileInView={reduce ? undefined : { opacity: 1, filter: "blur(0px)", y: 0 }} viewport={IN_VIEW} transition={reduce?{duration:0}:reveal(0.15)}>
                {copy.subhead}
              </motion.p>
              <motion.div className="art:mt-8" initial={reduce?false:{ opacity: 0, y: 12 }} animate={reduce?{opacity:1,y:0,filter:"blur(0px)"}:undefined} whileInView={reduce ? undefined : { opacity: 1, y: 0 }} viewport={IN_VIEW} transition={reduce?{duration:0}:reveal(0.24)}>
                <motion.a whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:bg-primary art:px-7 art:text-primary-foreground art:hover:bg-primary/90 art:h-9 art:rounded-full" href={copy.cta.href} tabIndex={0}>
                  {copy.cta.label}
                </motion.a>
              </motion.div>
            </div>
          </div>
          <FaqAccordion items={items} defaultOpen={items[0]?.id}/>
        </div>
      </section>
    </div>);
}

// @zeus-internal
import { ArtemisTextReveal } from "../../../../lib/text-reveal";
export function TextReveal({ lines, className }: {
    lines: string[];
    className?: string;
}) { return <ArtemisTextReveal as="h2" text={lines} yOffset="40%" stagger={.09} className={className} whileInView={false}/>; }

"use client";
// @zeus-internal
import { ChevronDown } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { ARTEMIS_EASE_OUT } from "./ease";
import { artemisCx } from "./utils";

export interface ArtemisDisclosureRowProps {
  id: string;
  open: boolean;
  onToggle: () => void;
  header: ReactNode;
  children: ReactNode;
  separated?: boolean;
  first?: boolean;
  last?: boolean;
  radius?: number;
  className?: string;
  surfaceClassName?: string;
  triggerClassName?: string;
  bodyClassName?: string;
  chevronClassName?: string;
}
export function ArtemisDisclosureRow({ id, open, onToggle, header, children, separated, first = true, last = true, radius = 28, className, surfaceClassName, triggerClassName, bodyClassName, chevronClassName }: ArtemisDisclosureRowProps) {
  const content = useRef<HTMLDivElement>(null);
  const [height, setHeight] = useState(0);
  const reduced = useReducedMotion() === true;
  useLayoutEffect(() => {
    const element = content.current;
    if (!element) return;
    const measure = () => setHeight(element.offsetHeight);
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    measure();
    return () => observer.disconnect();
  }, []);
  const rowTiming = reduced ? { duration: 0 } : { type: "spring", duration: .55, bounce: .38 } as const;
  return <motion.div layout="position" initial={false} animate={{ marginTop: separated ? 12 : 0 }} transition={rowTiming} className={className}>
    <motion.div data-state={open ? "open" : "closed"} initial={false} animate={{ borderTopLeftRadius: first ? radius : 0, borderTopRightRadius: first ? radius : 0, borderBottomLeftRadius: last ? radius : 0, borderBottomRightRadius: last ? radius : 0 }} transition={rowTiming} className={artemisCx("art:overflow-hidden art:bg-background art:text-card-foreground", surfaceClassName)}>
      <button id={`${id}-trigger`} type="button" aria-expanded={open} aria-controls={`${id}-content`} onClick={onToggle} className={artemisCx("art:flex art:w-full art:items-center art:gap-3 art:text-left art:outline-none art:transition-colors art:focus-visible:bg-muted/25 art:disabled:pointer-events-none art:focus-visible:ring-2 art:focus-visible:ring-inset art:focus-visible:ring-ring", triggerClassName)}>
        {header}
        <motion.span aria-hidden className={artemisCx("art:grid art:size-4 art:shrink-0 art:place-items-center art:text-muted-foreground", chevronClassName)} initial={false} animate={{ rotate: open ? 180 : 0 }} transition={reduced ? { duration: 0 } : { type: "spring", duration: .42, bounce: .28 }}><ChevronDown className="art:size-4"/></motion.span>
      </button>
      <motion.section id={`${id}-content`} aria-labelledby={`${id}-trigger`} aria-hidden={!open} initial={false} animate={{ height: open ? height : 0 }} transition={reduced ? { duration: 0 } : { type: "spring", duration: open ? .58 : .46, bounce: open ? .32 : .26 }} className="art:overflow-hidden">
        <motion.div ref={content} inert={!open} initial={false} animate={{ opacity: open ? 1 : 0 }} transition={{ duration: reduced ? 0 : .18, ease: ARTEMIS_EASE_OUT }} className={bodyClassName}>{children}</motion.div>
      </motion.section>
    </motion.div>
  </motion.div>;
}

"use client";
// @zeus-internal
import { useId, useState } from "react";
import { ArtemisDisclosureRow } from "./disclosure-row";

export interface ArtemisFaqItem {
  id: string;
  question: string;
  answer: string;
}
/** Single-open answers separate the adjoining closed groups as they expand. */
export function ArtemisFaqAccordion({ items, defaultOpen }: {
  items: ArtemisFaqItem[];
  defaultOpen?: string;
}) {
  const instance = useId();
  const [selected, select] = useState(defaultOpen);
  return <div className="art:w-full art:min-w-0">
    {items.map((item, index) => {
      const open = selected === item.id;
      const beforeOpen = index > 0 && items[index - 1].id === selected;
      const afterOpen = index + 1 < items.length && items[index + 1].id === selected;
      return <ArtemisDisclosureRow
        key={item.id}
        id={`${instance}-${item.id}`}
        open={open}
        separated={index > 0 && (open || beforeOpen)}
        first={index === 0 || open || beforeOpen}
        last={index === items.length - 1 || open || afterOpen}
        radius={28}
        onToggle={() => select(open ? undefined : item.id)}
        header={<span className="art:min-w-0 art:flex-1 art:text-[15px] art:font-medium art:text-foreground">{item.question}</span>}
        surfaceClassName="art:bg-card"
        triggerClassName="art:min-h-[58px] art:gap-4 art:px-5 art:py-0"
        chevronClassName="art:size-6"
        bodyClassName="art:px-5 art:pb-5 art:text-sm art:leading-6 art:text-muted-foreground"
      >{item.answer}</ArtemisDisclosureRow>;
    })}
  </div>;
}

"use client";
// @zeus-internal
import { ArtemisWordEntrance } from "./word-entrance";
import type { ArtemisWordMotionOptions } from "./word-motion";
export interface ArtemisTextRevealProps extends ArtemisWordMotionOptions {
  text: string | string[];
  as?: "span" | "div" | "p" | "h1" | "h2" | "h3" | "h4";
  className?: string;
  once?: boolean;
  amount?: number;
  whileInView?: boolean;
}
export function ArtemisTextReveal({
  text,
  as: Tag = "span",
  className = "",
  stagger = 0.06,
  yOffset = "24%",
  delay = 0,
  whileInView = true,
  ...options
}: ArtemisTextRevealProps) {
  const lines = Array.isArray(text) ? text : [text];
  let offset = 0;
  return (
    <Tag className={`art:block ${className}`}>
      {lines.map((line, index) => {
        const words = line.split(/\s+/),
          start = offset;
        offset += words.length;
        return (
          <ArtemisWordEntrance
            key={index}
            words={words}
            stagger={stagger}
            delay={delay + start * stagger}
            yOffset={yOffset}
            entered={whileInView ? undefined : true}
            {...options}
          />
        );
      })}
    </Tag>
  );
}

"use client";
// @zeus-internal
import { motion, useInView, useReducedMotion } from "motion/react";
import { useRef } from "react";
import { artemisWordMotion, type ArtemisWordMotionOptions } from "./word-motion";
export interface ArtemisWordEntranceProps {
  words: string[];
  className?: string;
  stagger?: number;
  delay?: number;
  blur?: number;
  yOffset?: string | number;
  spring?: ArtemisWordMotionOptions["spring"];
  once?: boolean;
  amount?: number;
  entered?: boolean;
}
export function ArtemisWordEntrance({
  words,
  className = "",
  stagger = 0.055,
  delay = 0,
  blur = 10,
  yOffset = "20%",
  amount = 0.4,
  spring,
  once = true,
  entered: externalEntry,
}: ArtemisWordEntranceProps) {
  const element = useRef<HTMLSpanElement>(null);
  const observed = useInView(element, { once, amount });
  const entered = externalEntry ?? observed;
  const reduced = useReducedMotion() === true;
  return (
    <span ref={element} className={`art:block ${className}`}>
      <span className="art:block">
        {words.map((word, index) => {
          const movement = artemisWordMotion(index, reduced, {
            delay,
            stagger,
            blur,
            yOffset,
            spring,
          });
          return (
            <motion.span
              key={index}
              className="art:inline-block"
              initial={movement.initial}
              // With reduced motion the words land on mount instead of waiting to be seen.
              animate={entered || reduced ? movement.animate : undefined}
              transition={movement.transition}
            >
              {word}
              {index < words.length - 1 && (
                <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">
                  {"\u00a0"}
                </span>
              )}
            </motion.span>
          );
        })}
      </span>
    </span>
  );
}

// @zeus-internal
import { ARTEMIS_EASE_OUT } from "./ease";
export interface ArtemisWordMotionOptions {
  delay?: number;
  stagger?: number;
  blur?: number;
  yOffset?: string | number;
  spring?: { stiffness?: number; damping?: number; mass?: number };
}
export function artemisWordMotion(
  index: number,
  reduced: boolean,
  { delay = 0, stagger = 0.055, blur = 10, yOffset = "20%", spring }: ArtemisWordMotionOptions = {}
) {
  const offset = delay + index * stagger;
  // The same start with reduced motion, so hydration matches the server; the words then land at once.
  return {
    initial: { opacity: 0, filter: `blur(${blur}px)`, y: yOffset },
    animate: { opacity: 1, filter: "blur(0px)", y: 0 },
    transition: reduced
      ? { duration: 0 }
      : {
          opacity: { duration: 0.7, delay: offset, ease: ARTEMIS_EASE_OUT },
          filter: { duration: 0.9, delay: offset, ease: ARTEMIS_EASE_OUT },
          y: {
            type: "spring" as const,
            stiffness: spring?.stiffness ?? 140,
            damping: spring?.damping ?? 26,
            mass: spring?.mass ?? 1.2,
            delay: offset,
          },
        },
  };
}
